/**
 * The byte-exact `override_gossip_config.json` serializer (CLIENT_SPEC.md §6.3).
 *
 * 🔴 `JSON.stringify(obj, null, 2)` will **not** do: it emits keys in insertion
 * order, so a parsed file with unknown keys would not round-trip to the
 * normative order, and it `\u`-escapes nothing but still disagrees with the
 * reference implementation on key ordering. This module reproduces exactly
 * `json.dumps(obj, indent=2, ensure_ascii=False, separators=(",", ": ")) + "\n"`
 * over the key order of §6.3(1)+(2) — the reference serializer the fixtures
 * were generated by (`tools/gen_fixtures.py`).
 */

/** §6.3(1): the fixed emission order for known keys. */
export const KNOWN_KEY_ORDER = Object.freeze([
  'chain',
  'root_node_ips',
  'try_new_peers',
  'reserved_peer_ips',
  'n_gossip_peers',
  'split_client_blocks',
] as const);

const KNOWN = new Set<string>(KNOWN_KEY_ORDER);

/**
 * Compare by Unicode **code point**, which is what Python's `sorted()` does.
 * JavaScript's default string comparison is by UTF-16 code unit, and the two
 * disagree above the BMP.
 */
export function compareCodePoints(a: string, b: string): number {
  // Spreading a string iterates CODE POINTS, which is exactly what Python's
  // `sorted()` compares; `.split('')` would split surrogate pairs.
  /* eslint-disable @typescript-eslint/no-misused-spread */
  const ai = [...a];
  const bi = [...b];
  /* eslint-enable @typescript-eslint/no-misused-spread */
  const n = Math.min(ai.length, bi.length);
  for (let i = 0; i < n; i++) {
    const x = ai[i]!.codePointAt(0)!;
    const y = bi[i]!.codePointAt(0)!;
    if (x !== y) return x < y ? -1 : 1;
  }
  return ai.length === bi.length ? 0 : ai.length < bi.length ? -1 : 1;
}

const ESCAPES: Record<string, string> = {
  '"': '\\"',
  '\\': '\\\\',
  '\b': '\\b',
  '\f': '\\f',
  '\n': '\\n',
  '\r': '\\r',
  '\t': '\\t',
};

/**
 * RFC 8259 minimal escaping: `"`, `\` and the C0 controls only. `/` is never
 * escaped and non-ASCII is emitted literally as UTF-8 (§6.3(6)).
 */
export function encodeJsonString(s: string): string {
  let out = '"';
  for (const ch of s) {
    const esc = ESCAPES[ch];
    if (esc !== undefined) {
      out += esc;
    } else if (ch < ' ') {
      out += '\\u' + ch.charCodeAt(0).toString(16).padStart(4, '0');
    } else {
      out += ch;
    }
  }
  return out + '"';
}

function encodeNumber(n: number): string {
  if (!Number.isFinite(n)) {
    throw new TypeError(`cannot serialize a non-finite number (${String(n)}) into a gossip config`);
  }
  // §6.3(7): integers carry no decimal point or exponent; a float in an unknown
  // key is re-emitted with the shortest round-trip representation, which is
  // exactly what `String(n)` produces in JavaScript.
  return String(n);
}

function encodeValue(value: unknown, indent: number): string {
  if (value === null) return 'null';
  switch (typeof value) {
    case 'boolean':
      return value ? 'true' : 'false';
    case 'number':
      return encodeNumber(value);
    case 'string':
      return encodeJsonString(value);
    default:
      break;
  }
  if (Array.isArray(value)) {
    // §6.3(4): an empty array is `[]` on one line; array order is preserved.
    if (value.length === 0) return '[]';
    const pad = ' '.repeat(indent + 2);
    const items = value.map((v) => pad + encodeValue(v, indent + 2));
    return '[\n' + items.join(',\n') + '\n' + ' '.repeat(indent) + ']';
  }
  if (typeof value === 'object') {
    // §6.3(2): nested object keys sort by code point.
    const obj = value as Record<string, unknown>;
    const keys = Object.keys(obj).sort(compareCodePoints);
    return encodeObject(obj, keys, indent);
  }
  throw new TypeError(`cannot serialize ${typeof value} into a gossip config`);
}

function encodeObject(obj: Record<string, unknown>, keys: string[], indent: number): string {
  if (keys.length === 0) return '{}';
  const pad = ' '.repeat(indent + 2);
  const parts = keys.map(
    (k) => pad + encodeJsonString(k) + ': ' + encodeValue(obj[k], indent + 2),
  );
  return '{\n' + parts.join(',\n') + '\n' + ' '.repeat(indent) + '}';
}

/**
 * Render a gossip config document to its normative bytes: known keys in the
 * fixed order, unknown keys after them sorted by code point, 2-space indent,
 * `": "` after each key, exactly one trailing `\n` (never `\r\n`).
 */
export function renderGossipConfig(cfg: Record<string, unknown>): string {
  const known = KNOWN_KEY_ORDER.filter((k) => Object.prototype.hasOwnProperty.call(cfg, k));
  const unknown = Object.keys(cfg)
    .filter((k) => !KNOWN.has(k))
    .sort(compareCodePoints);
  return encodeObject(cfg, [...known, ...unknown], 0) + '\n';
}
